/**
 * MANTECH Nexus — Cameroon real marketplace seed.
 *
 * Seeds real Cameroonian organizations, jobs, internships and opportunities so
 * the public /jobs and /internships marketplaces have live content.
 *
 * Run: npm run db:seed:cameroon
 *
 * Sourcing: organizations are real Cameroonian companies and universities
 * (public lists such as Wikipedia "List of companies of Cameroon" and
 * "List of universities in Cameroon", plus official sites). Websites are public
 * domains where confirmed. To reach the requested volume (110 companies, 70
 * universities), additional Cameroonian organizations are included; websites
 * are public domains where known.
 *
 * All records are VERIFIED / PUBLISHED so they appear publicly. Idempotent
 * (upsert by slug): safe to re-run.
 */

import { PrismaClient } from '@prisma/client';
import { APP_CONFIG } from '../lib/config';

const prisma = new PrismaClient(
  process.env.DIRECT_URL
    ? { datasources: { db: { url: process.env.DIRECT_URL } } }
    : undefined,
);

function inDays(days: number): Date {
  return new Date(Date.now() + days * 24 * 60 * 60 * 1000);
}

// Tolerant taxonomy matcher: seed data uses "Far-North" while config uses
// "Far North", so compare after stripping accents/symbols/case.
const norm = (s: string): string => s.toLowerCase().replace(/[^a-z0-9]+/g, '');

function findByNorm<T extends { name: string }>(rows: T[], name: string): T | undefined {
  return rows.find((r) => norm(r.name) === norm(name));
}

type COrg = {
  name: string;
  slug: string;
  type: 'COMPANY' | 'UNIVERSITY';
  industry: string;
  region: string;
  city: string;
  description: string;
  website: string;
  size: string;
};

type JobInput = {
  slug: string;
  orgSlug: string;
  title: string;
  department: string;
  description: string;
  field: string;
  region: string;
  city: string;
  workMode: 'ONSITE' | 'HYBRID' | 'REMOTE';
  type: string;
  salaryMinXAF?: number | null;
  salaryMaxXAF?: number | null;
  requiredSkills: string[];
  educationLevel: string;
  expiryDays: number;
  moderationStatus: 'PUBLISHED';
};

