async function main() {
  console.log('🌱 Seeding MANTECH Nexus Cameroon marketplace data...');

  // ── 1. Taxonomy (regions, fields) ───────────────────────────────────────────
  for (const region of APP_CONFIG.cameroonRegions) {
    await prisma.region.upsert({
      where: { name: region.name },
      update: {},
      create: {
        name: region.name,
        code: region.id.toUpperCase(),
        capital: region.capital,
        country: 'Cameroon',
      },
    });
  }

  for (const field of APP_CONFIG.professionalFields) {
    await prisma.field.upsert({
      where: { name: field.name },
      update: {},
      create: {
        name: field.name,
        slug: field.slug,
        category: field.category,
        description: `${field.name} professional field in Cameroon`,
      },
    });
  }

  // Pre-load reference tables once
  const regions = await prisma.region.findMany();
  const industries = await prisma.industry.findMany();
  const fields = await prisma.field.findMany();

  // ── 2. Organizations ─────────────────────────────────────────────────────────
  const allOrgs = [...COMPANIES, ...UNIVERSITIES];
  for (const org of allOrgs) {
    const regionRow = findByNorm(regions, org.region);
    const industryRow = industries.find((i) => i.name === org.industry);

    await prisma.organization.upsert({
      where: { slug: org.slug },
      update: {
        name: org.name,
        type: org.type,
        description: org.description,
        website: org.website,
        size: org.size,
        verificationStatus: 'VERIFIED',
        verifiedAt: new Date(),
        regionId: regionRow?.id,
        industryId: industryRow?.id,
        city: org.city,
      },
      create: {
        name: org.name,
        slug: org.slug,
        type: org.type,
        description: org.description,
        website: org.website,
        size: org.size,
        verificationStatus: 'VERIFIED',
        verifiedAt: new Date(),
        regionId: regionRow?.id,
        industryId: industryRow?.id,
        city: org.city,
      },
    });
  }
  console.log(`  ✓ ${allOrgs.length} organizations upserted`);

  // Pre-load org map for fast listing insertions
  const orgMap = new Map((await prisma.organization.findMany()).map((o) => [o.slug, o]));

  // ── 3. Jobs ──────────────────────────────────────────────────────────────────
  let jobCount = 0;
  for (const j of JOBS) {
    const org = orgMap.get(j.orgSlug);
    if (!org) {
      console.warn(`  ⚠ Job "${j.slug}": org "${j.orgSlug}" not found, skipping`);
      continue;
    }
    const regionRow = findByNorm(regions, j.region);
    const fieldRow = fields.find((f) => f.name === j.field || f.slug === j.field);

    await prisma.job.upsert({
      where: { slug: j.slug },
      update: {
        title: j.title,
        description: j.description,
        department: j.department,
        type: j.type as 'FULL_TIME' | 'PART_TIME' | 'CONTRACT' | 'FREELANCE',
        workMode: j.workMode,
        city: j.city,
        educationLevel: j.educationLevel,
        salaryMinXAF: j.salaryMinXAF ?? null,
        salaryMaxXAF: j.salaryMaxXAF ?? null,
        expiryDate: inDays(j.expiryDays),
        moderationStatus: j.moderationStatus,
        requiredSkills: j.requiredSkills,
      },
      create: {
        slug: j.slug,
        organizationId: org.id,
        regionId: regionRow?.id,
        fieldId: fieldRow?.id,
        title: j.title,
        description: j.description,
        department: j.department,
        type: j.type as 'FULL_TIME' | 'PART_TIME' | 'CONTRACT' | 'FREELANCE',
        workMode: j.workMode,
        city: j.city,
        educationLevel: j.educationLevel,
        salaryMinXAF: j.salaryMinXAF ?? null,
        salaryMaxXAF: j.salaryMaxXAF ?? null,
        expiryDate: inDays(j.expiryDays),
        moderationStatus: j.moderationStatus,
        requiredSkills: j.requiredSkills,
      },
    });
    jobCount++;
  }
  console.log(`  ✓ ${jobCount} jobs upserted`);

  // ── 4. Internships ───────────────────────────────────────────────────────────
  let internCount = 0;
  for (const intern of INTERNSHIPS) {
    const org = orgMap.get(intern.orgSlug);
    if (!org) {
      console.warn(`  ⚠ Internship "${intern.slug}": org "${intern.orgSlug}" not found, skipping`);
      continue;
    }
    const regionRow = findByNorm(regions, intern.region);
    const fieldRow = fields.find((f) => f.name === intern.field || f.slug === intern.field);

    await prisma.internshipOpportunity.upsert({
      where: { slug: intern.slug },
      update: {
        title: intern.title,
        description: intern.description,
        department: intern.department,
        workMode: intern.workMode,
        city: intern.city,
        durationMonths: intern.durationMonths,
        isPaid: intern.isPaid,
        allowanceXAF: intern.allowanceXAF,
        positions: intern.positions,
        educationLevel: intern.educationLevel,
        deadline: inDays(intern.deadlineDays),
        moderationStatus: intern.moderationStatus,
        requiredSkills: intern.skills,
      },
      create: {
        slug: intern.slug,
        organizationId: org.id,
        regionId: regionRow?.id,
        fieldId: fieldRow?.id,
        title: intern.title,
        description: intern.description,
        department: intern.department,
        workMode: intern.workMode,
        city: intern.city,
        durationMonths: intern.durationMonths,
        isPaid: intern.isPaid,
        allowanceXAF: intern.allowanceXAF,
        positions: intern.positions,
        educationLevel: intern.educationLevel,
        deadline: inDays(intern.deadlineDays),
        moderationStatus: intern.moderationStatus,
        requiredSkills: intern.skills,
      },
    });
    internCount++;
  }
  console.log(`  ✓ ${internCount} internships upserted`);

  // ── 5. Opportunities (industrial placements) ─────────────────────────────────
  let oppCount = 0;
  for (const opp of OPPORTUNITIES) {
    const org = orgMap.get(opp.orgSlug);
    if (!org) {
      console.warn(`  ⚠ Opportunity "${opp.slug}": org "${opp.orgSlug}" not found, skipping`);
      continue;
    }
    const regionRow = findByNorm(regions, opp.region);
    const fieldRow = fields.find((f) => f.name === opp.field || f.slug === opp.field);

    await prisma.internshipOpportunity.upsert({
      where: { slug: opp.slug },
      update: {
        title: opp.title,
        description: opp.description,
        department: opp.department,
        workMode: opp.workMode,
        city: opp.city,
        durationMonths: opp.durationMonths,
        isPaid: opp.isPaid,
        allowanceXAF: opp.allowanceXAF,
        positions: opp.positions,
        educationLevel: opp.educationLevel,
        deadline: inDays(opp.deadlineDays),
        moderationStatus: opp.moderationStatus,
        requiredSkills: opp.skills,
      },
      create: {
        slug: opp.slug,
        organizationId: org.id,
        regionId: regionRow?.id,
        fieldId: fieldRow?.id,
        title: opp.title,
        description: opp.description,
        department: opp.department,
        workMode: opp.workMode,
        city: opp.city,
        durationMonths: opp.durationMonths,
        isPaid: opp.isPaid,
        allowanceXAF: opp.allowanceXAF,
        positions: opp.positions,
        educationLevel: opp.educationLevel,
        deadline: inDays(opp.deadlineDays),
        moderationStatus: opp.moderationStatus,
        requiredSkills: opp.skills,
      },
    });
    oppCount++;
  }
  console.log(`  ✓ ${oppCount} opportunities upserted`);

  console.log('✅ Cameroon marketplace seed complete!');
}

main()
  .catch(async (e) => {
    console.error('❌ Seed failed:', e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
